{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows sustained negative sentiment (e.g., multiple -0.25 or 0.00 values), indicating market pessimism.",
    "Increase forecast sensitivity to recent price spikes — if true outcome exceeds model forecast by >5% after a spike, adjust upward by 2–3% to capture momentum.",
    "Apply mean reversion bias: if model consistently overpredicts prices in 3–5 consecutive days, reduce forecast by 1–2% per day to align with historical volatility patterns.",
    "When sentiment shifts from neutral to positive (e.g., 0.00 → 0.50 or 0.67), increase forecast by 1–3% to reflect bullish momentum.",
    "Correct for lag: if model forecasts are 2–3 days behind true price movements, apply a 1–2% upward adjustment to catch up with recent trends.",
    "Avoid over-optimism in early forecast windows — if sentiment is neutral or slightly negative, cap forecast increases to 1–2% to prevent overshoot."
  ]
}
